using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-1", 2, 9.99m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual((2, 9.99m), _cart.Items["SKU-1"]);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantitiesAccumulate()
    {
        _cart.AddItem("SKU-1", 1, 5.00m);
        _cart.AddItem("SKU-1", 3, 5.00m);

        Assert.AreEqual(4, _cart.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_DifferentSkus_BothPresent()
    {
        _cart.AddItem("A", 1, 1.00m);
        _cart.AddItem("B", 2, 2.00m);

        Assert.HasCount(2, _cart.Items);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 1.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", qty, 1.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 1, -0.01m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _cart.AddItem("FREE", 1, 0m);

        Assert.HasCount(1, _cart.Items);
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-1", 1, 10.00m);

        _cart.RemoveItem("SKU-1");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonexistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsExactly<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _cart.AddItem("SKU-1", 3, 10.00m);

        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsAll()
    {
        _cart.AddItem("A", 2, 5.00m);
        _cart.AddItem("B", 1, 15.00m);

        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public void ApplyCoupon_InvalidCode_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_ValidCode_StoresCode()
    {
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual("SAVE10", _cart.AppliedCoupon);
    }

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF", 50.00)]
    public void CalculateTotal_WithKnownCoupon_AppliesDiscount(string code, double expected)
    {
        _cart.AddItem("SKU-1", 1, 100.00m);
        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expected, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_WithUnknownCoupon_NoDiscount()
    {
        _cart.AddItem("SKU-1", 1, 100.00m);
        _cart.ApplyCoupon("BOGUS");

        Assert.AreEqual(100.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_CouponOnEmptyCart_ReturnsZero()
    {
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedBySecondCoupon_UsesLatest()
    {
        _cart.AddItem("SKU-1", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }
}

